package app.plugxaura.iptv;

import android.content.*;
import android.os.Bundle;
import android.os.Handler;
import android.text.*;
import android.view.*;
import android.widget.*;
import androidx.appcompat.app.AppCompatActivity;
import androidx.recyclerview.widget.*;
import com.google.gson.*;
import java.text.*;
import java.util.*;

public class HomeActivity extends AppCompatActivity {
    private final Handler timer=new Handler();private int chosenPlaylist=0,shownPlaylist=0,shownCategory=0;private boolean favorites=false,inChannels=false;
    private LinearLayout root;private android.app.Dialog maintenanceDialog;private TextView maintenanceMessage;private Button refreshButton;private boolean manualRefresh=false;
    private final Runnable refresh=new Runnable(){public void run(){loadCatalog(false);timer.postDelayed(this,240000);}};
    private JsonObject catalog(){return PlugXApp.catalog();}
    @Override public void onCreate(Bundle b){super.onCreate(b);Ui.applyTheme(this);renderHome();loadCatalog(false);}
    @Override protected void onResume(){super.onResume();Ui.applyTheme(this);if(catalog()!=null){if(inChannels)showChannels(shownPlaylist,shownCategory,favorites);else renderHome();syncMaintenanceState();sendHomePresence();}timer.removeCallbacks(refresh);timer.postDelayed(refresh,240000);}
    @Override protected void onPause(){timer.removeCallbacks(refresh);super.onPause();}
    @Override protected void onDestroy(){timer.removeCallbacksAndMessages(null);if(maintenanceDialog!=null)maintenanceDialog.dismiss();super.onDestroy();}
    private void sendHomePresence(){JsonObject body=new JsonObject();body.addProperty("channel_id",0);body.addProperty("playlist_id",0);body.addProperty("version_code",BuildConfig.VERSION_CODE);body.addProperty("proxy_active",PlugXApp.prefs(this).getBoolean("proxy_enabled",false));PlugXApp.request(this,"heartbeat",body,(result,error)->{});}
    private void loadCatalog(boolean showError){PlugXApp.request(this,"bootstrap",null,(value,error)->{boolean wasManual=manualRefresh;manualRefresh=false;if(error!=null){if(refreshButton!=null){refreshButton.setEnabled(true);refreshButton.setText("Refresh");}if(showError)Ui.alert(this,"Refresh",error.getMessage());if(error.getMessage()!=null&&error.getMessage().contains("Session expired")){PlugXApp.prefs(this).edit().remove("token").apply();startActivity(new Intent(this,LoginActivity.class));finish();}return;}PlugXApp.catalog(this,value);if(inChannels)showChannels(shownPlaylist,shownCategory,favorites);else renderHome();syncMaintenanceState();sendHomePresence();if(wasManual)Toast.makeText(this,"Channels are up to date",Toast.LENGTH_SHORT).show();});}
    private void syncMaintenanceState(){JsonObject settings=PlugXApp.object(catalog(),"player_settings");if(!PlugXApp.bool(settings,"maintenance_mode")){if(maintenanceDialog!=null){maintenanceDialog.dismiss();maintenanceDialog=null;maintenanceMessage=null;}return;}if(inChannels)renderHome();String message=PlugXApp.str(settings,"maintenance_text","Server under maintenance. Please check back shortly.");if(maintenanceDialog!=null&&maintenanceDialog.isShowing()){if(maintenanceMessage!=null)maintenanceMessage.setText(android.text.Html.fromHtml(message));return;}
        LinearLayout box=Ui.column(this);box.setPadding(Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,24),Ui.dp(this,22));box.setBackground(Ui.shape(Ui.CARD,Ui.RED,Ui.dp(this,22)));
        TextView icon=Ui.text(this,"🛠️",34,true);icon.setGravity(Gravity.CENTER);box.addView(icon,Ui.margins(this,-1,52,3));TextView title=Ui.text(this,"Server Maintenance",23,true);title.setGravity(Gravity.CENTER);box.addView(title,Ui.margins(this,-1,48,3));TextView hint=Ui.muted(this,"Live TV will return shortly",14);hint.setGravity(Gravity.CENTER);box.addView(hint,Ui.margins(this,-1,32,2));
        maintenanceMessage=Ui.text(this,"",16,false);maintenanceMessage.setGravity(Gravity.CENTER);maintenanceMessage.setText(android.text.Html.fromHtml(message));maintenanceMessage.setPadding(0,Ui.dp(this,12),0,Ui.dp(this,12));ScrollView body=new ScrollView(this);body.setFillViewport(false);body.addView(maintenanceMessage);box.addView(body,new LinearLayout.LayoutParams(-1,Ui.dp(this,160)));
        Button check=Ui.button(this,"Check again");box.addView(check,Ui.margins(this,-1,52,4));check.setOnClickListener(v->{check.setEnabled(false);check.setText("Checking…");loadCatalog(true);timer.postDelayed(()->{if(maintenanceDialog!=null&&maintenanceDialog.isShowing()){check.setEnabled(true);check.setText("Check again");}},1200);});
        maintenanceDialog=new android.app.Dialog(this);maintenanceDialog.setContentView(box);maintenanceDialog.setCancelable(false);android.view.Window window=maintenanceDialog.getWindow();if(window!=null)window.setBackgroundDrawableResource(android.R.color.transparent);maintenanceDialog.show();window=maintenanceDialog.getWindow();if(window!=null)window.setLayout((int)(getResources().getDisplayMetrics().widthPixels*.88f),-2);
    }
    private void scaffold(){ScrollView scroll=new ScrollView(this);scroll.setFillViewport(true);scroll.setBackgroundColor(Ui.BG);root=Ui.column(this);root.setPadding(Ui.dp(this,12),Ui.dp(this,10),Ui.dp(this,12),Ui.dp(this,16));scroll.addView(root);setContentView(scroll);}
    private void heading(String text){TextView h=Ui.text(this,text,22,true);h.setPadding(Ui.dp(this,6),Ui.dp(this,12),0,Ui.dp(this,6));root.addView(h);}
    private void addHomeHeader(LinearLayout target){
        JsonObject data=catalog();int widthDp=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density);boolean wide=widthDp>=600;
        LinearLayout top=Ui.row(this);ImageView icon=new ImageView(this);icon.setImageResource(R.drawable.plugx_logo);top.addView(icon,Ui.margins(this,wide?56:64,wide?56:64,3));
        LinearLayout names=Ui.column(this);String name=PlugXApp.str(PlugXApp.object(data,"user"),"display_name","");TextView welcome=Ui.text(this,name.isEmpty()?"PLUG X IPTV":"Welcome, "+name,wide?18:22,true);welcome.setSingleLine(true);welcome.setEllipsize(TextUtils.TruncateAt.END);names.addView(welcome);TextView sync=Ui.muted(this,Ui.lastSync(this),wide?11:13);sync.setSingleLine(true);sync.setEllipsize(TextUtils.TruncateAt.END);names.addView(sync);
        TextView premium=Ui.text(this,"✦  PLUG X PREMIUM",11,true);premium.setTextColor(0xff8b1c35);premium.setLetterSpacing(.09f);premium.setPadding(Ui.dp(this,9),0,Ui.dp(this,9),0);premium.setBackground(Ui.shape(0xffffe8b7,0xffbd8a35,Ui.dp(this,10)));names.addView(premium,Ui.margins(this,-2,26,2));top.addView(names,new LinearLayout.LayoutParams(0,-2,1));
        LinearLayout controls=Ui.row(this);Button notice=Ui.button(this,"Notices"),settings=Ui.button(this,"Settings"),reload=Ui.button(this,"Refresh"),logout=Ui.button(this,"Logout");refreshButton=reload;
        for(Button b:new Button[]{notice,settings,reload,logout}){b.setTextSize(wide?11:widthDp<420?11:13);b.setPadding(Ui.dp(this,3),0,Ui.dp(this,3),0);b.setMinWidth(0);b.setMinimumWidth(0);LinearLayout.LayoutParams p=wide?new LinearLayout.LayoutParams(Ui.dp(this,widthDp<780?74:86),Ui.dp(this,42)):new LinearLayout.LayoutParams(0,Ui.dp(this,44),1);p.setMargins(Ui.dp(this,3),0,Ui.dp(this,3),0);controls.addView(b,p);}
        if(wide){top.addView(controls);target.addView(top,Ui.margins(this,-1,68,2));}else{target.addView(top);target.addView(controls,Ui.margins(this,-1,50,2));}
        settings.setOnClickListener(v->startActivity(new Intent(this,SettingsActivity.class)));reload.setOnClickListener(v->{manualRefresh=true;reload.setEnabled(false);reload.setText("Updating…");loadCatalog(true);});notice.setOnClickListener(v->showNotices());logout.setOnClickListener(v->new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Sign out?").setMessage("You can sign in again with your user ID and password.").setNegativeButton("Stay",null).setPositiveButton("Sign out",(dialog,which)->PlugXApp.request(this,"logout",null,(r,e)->{PlugXApp.prefs(this).edit().remove("token").apply();startActivity(new Intent(this,LoginActivity.class));finishAffinity();})).show());
    }
    private void renderHome(){inChannels=false;if(chosenPlaylist>0){renderPlaylist();return;}scaffold();JsonObject data=catalog();addHomeHeader(root);
        if(data==null){heading("Loading channels…");return;}
        heading("Playlists");JsonArray playlists=PlugXApp.array(data,"playlists");if(playlists.size()==0)root.addView(Ui.muted(this,"No playlist has been added yet.",16));
        addGrid(playlists,(item)->{int id=PlugXApp.integer(item,"id",0);FrameLayout b=Ui.imageCard(this,PlugXApp.str(item,"name","Playlist"),PlugXApp.str(item,"image",""));b.setContentDescription("Playlist "+PlugXApp.str(item,"name",""));b.setOnClickListener(v->{chosenPlaylist=id;renderHome();});return b;});
        heading("Explore live TV");JsonArray categories=PlugXApp.array(data,"categories");addGrid(categories,(item)->{int id=PlugXApp.integer(item,"id",0),pid=PlugXApp.integer(item,"playlist_id",0);FrameLayout b=Ui.imageCard(this,PlugXApp.str(item,"name","Category"),PlugXApp.str(item,"image",""));b.setContentDescription("Category "+PlugXApp.str(item,"name",""));b.setOnClickListener(v->showChannels(pid,id,false));return b;});
        JsonArray cards=PlugXApp.array(data,"cards");heading("Your channels");addGrid(cards,(item)->{String type=PlugXApp.str(item,"target_type","all");int id=PlugXApp.integer(item,"target_id",0);FrameLayout b=Ui.imageCard(this,PlugXApp.str(item,"label",type),PlugXApp.str(item,"image",""));b.setOnClickListener(v->{if(type.equals("favorites"))showChannels(0,0,true);else if(type.equals("category"))showChannels(0,id,false);else if(type.equals("playlist"))showChannels(id,0,false);else showChannels(0,0,false);});return b;});
    }
    private void renderPlaylist(){inChannels=false;scaffold();JsonObject data=catalog();addHomeHeader(root);Button back=Ui.button(this,"← All playlists");root.addView(back,Ui.margins(this,-1,50,2));back.setOnClickListener(v->{chosenPlaylist=0;renderHome();});String name=playlistName(chosenPlaylist);heading(name);TextView subtitle=Ui.muted(this,"Choose a category or browse every live channel in this playlist.",14);root.addView(subtitle,Ui.margins(this,-1,-2,4));Button all=Ui.button(this,"▶  Watch all channels");root.addView(all,Ui.margins(this,-1,54,4));all.setOnClickListener(v->showChannels(chosenPlaylist,0,false));heading("Categories");JsonArray categories=new JsonArray();for(JsonElement e:PlugXApp.array(data,"categories")){JsonObject o=e.getAsJsonObject();if(PlugXApp.integer(o,"playlist_id",0)==chosenPlaylist)categories.add(o);}if(categories.size()==0)root.addView(Ui.muted(this,"No categories are available for this playlist.",16));addGrid(categories,(item)->{int id=PlugXApp.integer(item,"id",0);FrameLayout card=Ui.imageCard(this,PlugXApp.str(item,"name","Category"),PlugXApp.str(item,"image",""));card.setContentDescription("Category "+PlugXApp.str(item,"name",""));card.setOnClickListener(v->showChannels(chosenPlaylist,id,false));return card;});}
    private interface CardMaker{View make(JsonObject object);}
    private void addGrid(JsonArray items,CardMaker maker){if(items.size()==0)return;int width=(int)(getResources().getDisplayMetrics().widthPixels/getResources().getDisplayMetrics().density);int columns=width>=1200?6:width>=900?5:width>=600?4:2;int height=width>=600?132:118;for(int i=0;i<items.size();i+=columns){LinearLayout row=Ui.row(this);for(int j=i;j<Math.min(i+columns,items.size());j++){View b=maker.make(items.get(j).getAsJsonObject());LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,Ui.dp(this,height),1);p.setMargins(Ui.dp(this,4),Ui.dp(this,4),Ui.dp(this,4),Ui.dp(this,4));row.addView(b,p);}for(int k=items.size()-i;k<columns;k++)row.addView(new View(this),new LinearLayout.LayoutParams(0,1,1));root.addView(row);}}
    private void showNotices(){JsonArray a=PlugXApp.array(catalog(),"notices");StringBuilder msg=new StringBuilder();for(JsonElement e:a){JsonObject o=e.getAsJsonObject();msg.append("• ").append(PlugXApp.str(o,"title","")).append("\n").append(PlugXApp.str(o,"body","")).append("\n\n");}Ui.alert(this,"Notices",msg.length()==0?"No notices yet.":msg.toString());}
    private ArrayList<JsonObject> channels(int pid,int cid,boolean fav,String query){ArrayList<JsonObject> list=new ArrayList<>();JsonObject data=catalog();if(data==null)return list;Set<String> saved=PlugXApp.prefs(this).getStringSet("favorites",Collections.emptySet());for(JsonElement e:PlugXApp.array(data,"channels")){JsonObject o=e.getAsJsonObject();int id=PlugXApp.integer(o,"id",0);if(pid>0&&PlugXApp.integer(o,"playlist_id",0)!=pid)continue;if(cid>0&&PlugXApp.integer(o,"category_id",0)!=cid)continue;if(fav&&!saved.contains(String.valueOf(id)))continue;if(!PlugXApp.str(o,"name","").toLowerCase(Locale.ROOT).contains(query.toLowerCase(Locale.ROOT)))continue;list.add(o);}return list;}
    private void showChannels(int pid,int cid,boolean fav){inChannels=true;shownPlaylist=pid;shownCategory=cid;favorites=fav;LinearLayout page=Ui.column(this);page.setBackgroundColor(Ui.BG);page.setPadding(Ui.dp(this,12),Ui.dp(this,8),Ui.dp(this,12),Ui.dp(this,8));setContentView(page);addHomeHeader(page);Button back=Ui.button(this,"← Home");page.addView(back,Ui.margins(this,-1,52,2));back.setOnClickListener(v->renderHome());String allLabel=PlugXApp.str(PlugXApp.object(catalog(),"brand"),"all_channels_label","All Channels");TextView title=Ui.text(this,fav?"Favorites":cid>0?categoryName(cid):pid>0?playlistName(pid):allLabel,24,true);page.addView(title,Ui.margins(this,-1,44,2));EditText search=Ui.edit(this,"Search channels");page.addView(search,Ui.margins(this,-1,50,2));RecyclerView list=new RecyclerView(this);list.setLayoutManager(new LinearLayoutManager(this));page.addView(list,new LinearLayout.LayoutParams(-1,0,1));ChannelAdapter adapter=new ChannelAdapter(channels(pid,cid,fav,""),pid,cid,fav);list.setAdapter(adapter);search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int start,int count,int after){}public void onTextChanged(CharSequence s,int start,int before,int count){adapter.replace(channels(pid,cid,fav,s.toString()));}public void afterTextChanged(Editable e){}});}
    private String playlistName(int id){for(JsonElement e:PlugXApp.array(catalog(),"playlists")){JsonObject o=e.getAsJsonObject();if(PlugXApp.integer(o,"id",0)==id)return PlugXApp.str(o,"name","Playlist");}return "Playlist";}
    private String categoryName(int id){for(JsonElement e:PlugXApp.array(catalog(),"categories")){JsonObject o=e.getAsJsonObject();if(PlugXApp.integer(o,"id",0)==id)return PlugXApp.str(o,"name","Category");}return "Category";}
    private void favorite(int id){Set<String> next=new HashSet<>(PlugXApp.prefs(this).getStringSet("favorites",Collections.emptySet()));String key=String.valueOf(id);boolean added=next.add(key);if(!added)next.remove(key);PlugXApp.prefs(this).edit().putStringSet("favorites",next).apply();Toast.makeText(this,added?"Added to Favorites":"Removed from Favorites",Toast.LENGTH_SHORT).show();if(favorites)showChannels(shownPlaylist,shownCategory,true);}
    @Override public void onBackPressed(){if(inChannels)renderHome();else if(chosenPlaylist>0){chosenPlaylist=0;renderHome();}else super.onBackPressed();}
    private class ChannelAdapter extends RecyclerView.Adapter<ChannelAdapter.Holder>{ArrayList<JsonObject> rows;final int pid,cid;final boolean fav;ChannelAdapter(ArrayList<JsonObject> r,int p,int c,boolean f){rows=r;pid=p;cid=c;fav=f;}void replace(ArrayList<JsonObject> r){rows=r;notifyDataSetChanged();}
        class Holder extends RecyclerView.ViewHolder{LinearLayout row;ImageView logo;TextView name,number;Holder(LinearLayout r,ImageView i,TextView n,TextView no){super(r);row=r;logo=i;name=n;number=no;}}
        @Override public Holder onCreateViewHolder(android.view.ViewGroup parent,int type){LinearLayout row=Ui.row(HomeActivity.this);row.setFocusable(true);row.setClickable(true);row.setLayoutParams(new RecyclerView.LayoutParams(-1,Ui.dp(HomeActivity.this,76)));row.setBackground(Ui.shape(Ui.CARD,0xff663241,Ui.dp(HomeActivity.this,16)));Ui.focus(row,HomeActivity.this);TextView number=Ui.text(HomeActivity.this,"",12,true);number.setTextColor(Ui.RED);number.setGravity(Gravity.CENTER);row.addView(number,Ui.margins(HomeActivity.this,38,38,3));FrameLayout art=new FrameLayout(HomeActivity.this);art.setBackground(Ui.shape(Ui.CARD2,0xff754655,Ui.dp(HomeActivity.this,10)));TextView marker=Ui.text(HomeActivity.this,"▶",17,true);marker.setTextColor(Ui.RED);marker.setGravity(Gravity.CENTER);art.addView(marker,new FrameLayout.LayoutParams(-1,-1));ImageView logo=new ImageView(HomeActivity.this);logo.setScaleType(ImageView.ScaleType.FIT_CENTER);art.addView(logo,new FrameLayout.LayoutParams(-1,-1));row.addView(art,Ui.margins(HomeActivity.this,48,48,3));LinearLayout labels=Ui.column(HomeActivity.this);TextView label=Ui.text(HomeActivity.this,"",16,true);label.setMaxLines(2);label.setEllipsize(android.text.TextUtils.TruncateAt.END);labels.addView(label);TextView caption=Ui.muted(HomeActivity.this,"LIVE CHANNEL",11);labels.addView(caption);row.addView(labels,new LinearLayout.LayoutParams(0,-2,1));return new Holder(row,logo,label,number);}
        @Override public void onBindViewHolder(Holder h,int pos){JsonObject item=rows.get(pos);int id=PlugXApp.integer(item,"id",0);h.number.setText(String.valueOf(PlugXApp.integer(item,"channel_number",pos+1)));h.name.setText(PlugXApp.str(item,"name","Channel"));ImageLoader.into(HomeActivity.this,PlugXApp.str(item,"logo",""),h.logo);h.row.setOnClickListener(v->{Intent play=new Intent(HomeActivity.this,PlayerActivity.class);play.putExtra("channel_id",id);play.putExtra("playlist_id",pid);play.putExtra("category_id",cid);play.putExtra("favorites",fav);startActivity(play);});h.row.setOnLongClickListener(v->{favorite(id);return true;});}
        @Override public int getItemCount(){return rows.size();}}
}
